def read_fixed_records(path, reclen):
    """Return records as [bytearray(reclen), original_length, rewritten].

    Like GnuCOBOL, a short trailing record is padded with binary zeros and is
    still returned as a record.
    """
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except FileNotFoundError:
        return []

    records = []
    for pos in range(0, len(data), reclen):
        chunk = data[pos:pos + reclen]
        rec = bytearray(chunk)
        if len(rec) < reclen:
            rec.extend(bytes(reclen - len(rec)))  # pad with LOW-VALUES
        records.append([rec, len(chunk), False])
    return records


def write_fixed_records(path, records):
    """Write records back.

    An untouched short trailing record keeps its short length; a record that
    was REWRITEn is written at the full FD record length.
    """
    with open(path, "wb") as fh:
        for entry in records:
            rec, orig_len, rewritten = entry
            if rewritten or orig_len == len(rec):
                fh.write(bytes(rec))
            else:
                fh.write(bytes(rec[:orig_len]))

